+    for (let index = 0; index < links.length; index++) await check(links[index], `post-${index + 1}`, 390);
+    if (errors.length) throw new Error(errors.join('\n'));
+    await writeFile(new URL('verification.json', directory), JSON.stringify({ results, errors }, null, 2));
+    console.log(JSON.stringify({ results, errors }, null, 2));
+} finally {
+    await browser.close();
+}
