diff --git a/Umbraco.Bench.Umbraco/Views/Shared/SiteLayout.cshtml b/Umbraco.Bench.Umbraco/Views/Shared/SiteLayout.cshtml
new file mode 100644
index 0000000000000000000000000000000000000000..af04730dc9de10c563fa5bcf1cdf1cafa101971b
