+@using System.Globalization
+@model Umbraco.Bench.Umbraco.Models.Blocks.PostListingModel
+<section id="journal" class="scroll-mt-8 border-t border-line pt-10 pb-20 md:pt-12 md:pb-28" aria-labelledby="journal-heading">
+    <div class="mb-9 flex flex-wrap items-end justify-between gap-4">
+        <div>
+            <p class="eyebrow mb-3 text-accent">The journal</p>
+            <h2 id="journal-heading" class="text-4xl font-medium tracking-[-0.045em] md:text-5xl">@Model.Heading</h2>
+        </div>
+        <p class="max-w-xs text-sm leading-relaxed text-muted">@Model.Intro</p>
+    </div>
+    <div class="grid gap-10 md:grid-cols-2 md:gap-8">
+        @foreach (var post in Model.Posts)
+        {
+            <article class="group">
+                <a href="@post.Url" class="block rounded-sm" aria-label="@post.Title">
+                    <div class="overflow-hidden rounded-[3px] bg-line">
+                        @if (post.ImageUrl is not null)
+                        {
+                            <img src="@post.ImageUrl" alt="@post.ImageAlt" width="1000" height="650" loading="lazy" class="aspect-[20/13] w-full object-cover transition-transform duration-500 motion-safe:group-hover:scale-105" />
+                        }
+                    </div>
+                    <div class="mt-5 flex flex-wrap items-center justify-between gap-3 text-[11px]">
+                        <span class="rounded-full border border-line px-3 py-1.5 font-medium">@post.Category</span>
+                        <span class="text-muted"><time datetime="@post.PublishedDate.ToString("yyyy-MM-dd")">@post.PublishedDate.ToString("dd MMM yyyy", CultureInfo.InvariantCulture)</time> <span class="px-1.5" aria-hidden="true">·</span> @post.ReadingMinutes min read</span>
+                    </div>
+                    <h3 class="mt-5 max-w-lg text-3xl leading-tight font-medium tracking-[-0.04em] transition-colors group-hover:text-accent md:text-[2.35rem]">@post.Title</h3>
+                    <p class="mt-4 max-w-lg text-base leading-relaxed text-muted">@post.Summary</p>
+                    <span class="mt-6 inline-flex items-center gap-4 text-sm font-semibold">Read the story <span class="text-accent" aria-hidden="true">↗</span></span>
+                </a>
+            </article>
+        }
+    </div>
+    @if (Model.Posts.Count == 0)
+    {
+        <p class="py-10 text-muted">The next connection is on its way. Check back for a new story.</p>
+    }
+</section>
