+@using Umbraco.Bench.Umbraco.Models
+@inherits UmbracoViewPage
+@{
+    var site = Model.AncestorOrSelf<BlogFrontPage>();
+    var siteName = site?.SiteName ?? "Common Ground";
+    var homeUrl = site?.Url() ?? "/";
+    var title = Model is BlogPost post ? post.Title : siteName;
+    var description = Model is BlogPost article ? article.Summary : site?.SiteDescription;
+}
+<!doctype html>
+<html lang="en">
+<head>
+    <meta charset="utf-8" />
+    <meta name="viewport" content="width=device-width, initial-scale=1" />
+    <title>@title@(title == siteName ? " — A journal for connected thinking" : " — " + siteName)</title>
+    <meta name="description" content="@description" />
+    <meta name="theme-color" content="#f6f5ef" />
+    <link rel="icon" href="~/favicon.svg" type="image/svg+xml" />
+    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
+</head>
+<body class="bg-paper text-ink antialiased">
+    <a href="#main" class="skip-link">Skip to content</a>
+    <div class="mx-auto max-w-[1320px] px-6 md:px-12 lg:px-16">
+        <header class="flex items-center justify-between gap-5 border-b border-line py-7 md:py-8">
+            <a class="flex items-center gap-3 text-xl font-semibold tracking-[-0.055em] md:text-2xl" href="@homeUrl" aria-label="@siteName home"><span class="brand-mark" aria-hidden="true"></span>@siteName<span class="text-accent" aria-hidden="true">.</span></a>
+            <nav aria-label="Main navigation" class="flex items-center gap-6 text-sm md:gap-9">
+                <a class="hover:text-accent" href="@(homeUrl + "#journal")">Journal <span class="ml-1 text-accent" aria-hidden="true">↗</span></a>
+                <a class="hidden text-muted hover:text-accent sm:inline" href="#about">About</a>
+            </nav>
+        </header>
+        <main id="main" tabindex="-1">@RenderBody()</main>
+        <footer id="about" class="border-t border-line py-9 md:py-12">
+            <div class="flex flex-col justify-between gap-6 md:flex-row md:items-start">
+                <div>
+                    <a class="text-xl font-semibold tracking-[-0.04em]" href="@homeUrl">@siteName<span class="text-accent">.</span></a>
+                    <p class="mt-3 max-w-md text-sm leading-relaxed text-muted">@site?.SiteDescription</p>
+                </div>
+                <a class="inline-flex items-center gap-5 text-sm font-medium hover:text-accent" href="@(homeUrl + "#journal")">Find your next connection <span aria-hidden="true">↗</span></a>
+            </div>
+            <div class="mt-10 flex flex-wrap justify-between gap-3 border-t border-line pt-5 text-[11px] text-muted">
+                <span>© @DateTime.Now.Year @siteName</span><span>Made with curiosity. Published with Umbraco.</span>
+            </div>
+        </footer>
+    </div>
+</body>
+</html>
