diff --git a/Umbraco.Bench.Frontend/check-blog.mjs b/Umbraco.Bench.Frontend/check-blog.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..d159ff88b518c0bc8bfec8bc68e3cfe355076704
--- /dev/null
+++ b/Umbraco.Bench.Frontend/check-blog.mjs
@@ -0,0 +1,55 @@
+import { chromium } from 'playwright';
+import { mkdir, writeFile } from 'node:fs/promises';
+
+const directory = new URL('../artifacts/', import.meta.url);
+await mkdir(directory, { recursive: true });
+const browser = await chromium.launch({ channel: 'msedge', headless: true });
+const context = await browser.newContext({ ignoreHTTPSErrors: true, viewport: { width: 1440, height: 1000 } });
+const page = await context.newPage();
+const errors = [];
+page.on('pageerror', error => errors.push(error.message));
+page.on('response', response => { if (response.status() >= 400) errors.push(`${response.status()} ${response.url()}`); });
+const base = 'https://localhost:44317';
+const results = [];
+async function check(path, name, width) {
+    await page.setViewportSize({ width, height: 1000 });
+    const response = await page.goto(base + path, { waitUntil: 'networkidle' });
+    await page.locator('footer').scrollIntoViewIfNeeded();
+    await page.waitForFunction(() => Array.from(document.images).every(image => image.complete));
+    const result = await page.evaluate(() => ({
+        title: document.title,
+        headings: Array.from(document.querySelectorAll('h1')).map(e => e.textContent),
+        blocks: Array.from(document.querySelectorAll('[data-content-element-type-alias]')).map(e => e.dataset.contentElementTypeAlias),
+        brokenImages: Array.from(document.images).filter(e => !e.naturalWidth).map(e => e.src),
+        overflow: document.documentElement.scrollWidth > innerWidth,
+        fallback: document.body.textContent.includes('Could not render component'),
+        articleParagraphs: document.querySelectorAll('.article-copy p').length,
+        cards: document.querySelectorAll('#journal article').length,
+        background: getComputedStyle(document.body).backgroundColor
+    }));
+    result.status = response.status();
+    result.viewport = width;
+    result.path = path;
+    results.push(result);
+    if (result.status !== 200 || result.headings.length !== 1 || result.brokenImages.length || result.overflow || result.fallback || result.blocks.length !== 2) throw new Error(JSON.stringify(result));
+    await page.evaluate(() => scrollTo({ top: 0, behavior: 'instant' }));
+    await page.screenshot({ path: new URL(`${name}-${width}.png`, directory).pathname.replace(/^\/(?=[A-Za-z]:)/, ''), fullPage: true });
+}
+try {
+    await check('/', 'home', 1440);
+    const links = await page.locator('#journal article a').evaluateAll(nodes => nodes.map(e => new URL(e.href).pathname));
+    if (links.length !== 2) throw new Error(`Expected two post links, got ${links.length}`);
+    for (let index = 0; index < links.length; index++) {
+        await check(links[index], `post-${index + 1}`, 1440);
+        if (!results.at(-1).articleParagraphs) throw new Error('Article body missing');
+        await page.getByRole('link', { name: 'Back to the journal' }).click();
+        await page.waitForURL('**/#journal');
+    }
+    await check('/', 'home', 390);
+    for (let index = 0; index < links.length; index++) await check(links[index], `post-${index + 1}`, 390);
+    if (errors.length) throw new Error(errors.join('\n'));
+    await writeFile(new URL('verification.json', directory), JSON.stringify({ results, errors }, null, 2));
+    console.log(JSON.stringify({ results, errors }, null, 2));
+} finally {
+    await browser.close();
+}
