 /* Site-wide styles below. Vue custom elements have their own shadow-DOM styles,
    but content passed into their slots renders in the light DOM and is styled here. */
+
+@theme {
+    --color-paper: #f6f5ef;
+    --color-ink: #232c27;
+    --color-muted: #60665e;
+    --color-line: #d9dcd2;
+    --color-accent: #a64025;
+    --font-sans: "Segoe UI", Arial, sans-serif;
+}
+
+html { scroll-behavior: smooth; }
+body { margin: 0; }
+::selection { background: #e5bd92; color: #232c27; }
+a:focus-visible { outline: 2px solid #a64025; outline-offset: 5px; }
+.eyebrow { font-size: 10px; font-weight: 600; letter-spacing: .15em; text-transform: uppercase; }
+.brand-mark { display: inline-block; position: relative; width: 30px; height: 25px; flex-shrink: 0; }
+.brand-mark::before, .brand-mark::after { content: ""; position: absolute; width: 23px; height: 23px; border: 2px solid #293d35; border-radius: 50%; top: 1px; }
+.brand-mark::after { left: 10px; border-color: #a64025; }
+.skip-link { position: absolute; top: -100px; left: 20px; z-index: 10; padding: 12px 20px; background: #232c27; color: #f6f5ef; }
+.skip-link:focus { top: 12px; }
+.umb-block-grid__layout-container { display: grid; grid-template-columns: repeat(var(--umb-block-grid--grid-columns, 12), minmax(0, 1fr)); }
+.umb-block-grid__layout-item { grid-column: span var(--umb-block-grid--item-column-span, 12); min-width: 0; }
+.article-copy { font-size: 18px; line-height: 1.85; color: #414b43; }
+.article-copy > * + * { margin-top: 1.5em; }
+.article-copy h2 { margin-top: 2.1em; color: #232c27; font-size: 30px; line-height: 1.25; font-weight: 600; letter-spacing: -.04em; }
+.article-copy h2 + p { margin-top: .8em; }
+.article-copy blockquote { margin: 2.3em 0; padding: 6px 0 6px 26px; border-left: 3px solid #a64025; color: #293d35; font-family: Georgia, serif; font-size: 29px; line-height: 1.45; }
+.article-copy a { text-decoration: underline; text-underline-offset: 3px; }
+.article-copy ul, .article-copy ol { padding-left: 1.5em; }
+.article-copy ul { list-style: disc; }
+.article-copy ol { list-style: decimal; }
+@media (max-width: 640px) {
+    .article-copy { font-size: 17px; }
+    .article-copy h2 { font-size: 27px; }
+    .article-copy blockquote { font-size: 25px; }
+}
+@media (prefers-reduced-motion: reduce) {
+    html { scroll-behavior: auto; }
+    *, *::before, *::after { transition: none !important; }
+}
